static inline __m128i k_exp(__m128i key, __m128i kg){
    kg = _mm_shuffle_epi32(kg, 0xff);
    key = _mm_xor_si128(key, _mm_slli_si128(key, 4));
    key = _mm_xor_si128(key, _mm_slli_si128(key, 4));
    key = _mm_xor_si128(key, _mm_slli_si128(key, 4));
    return _mm_xor_si128(key, kg);
}
static void expand128(const uint8_t *k, __m128i *rk){
    rk[0] = _mm_loadu_si128((const __m128i*)k);
#define E(i,c) rk[i] = k_exp(rk[i-1], _mm_aeskeygenassist_si128(rk[i-1], c));
    E(1,0x01) E(2,0x02) E(3,0x04) E(4,0x08) E(5,0x10) E(6,0x20) E(7,0x40) E(8,0x80) E(9,0x1b) E(10,0x36)
#undef E
}
static inline __m128i aes_enc(const __m128i *rk, __m128i b){
    b = _mm_xor_si128(b, rk[0]);
    for (int i = 1; i < 10; i++) b = _mm_aesenc_si128(b, rk[i]);
    return _mm_aesenclast_si128(b, rk[10]);
